-- Web push sender wiring. Every new message is POSTed to the push sender
-- (api/push on Vercel), which works out who should be notified (group: all
-- members but the sender; DM: the recipient only) and sends the pushes.
--
-- push_config holds the sender URL, the shared secret the sender checks, and
-- the VAPID key pair. The server creates the keys the first time push is
-- turned on (GET /api/push/key), so no key ever has to be generated by hand.
-- The table has row-level security on and no policies: only the service role
-- (the Vercel functions) and the trigger below can read it, never the app.

create table public.push_config (
  id boolean primary key default true check (id),
  url text,
  secret text not null default encode(extensions.gen_random_bytes(24), 'hex'),
  vapid_public_key text,
  vapid_private_key text,
  updated_at timestamptz not null default now()
);

alter table public.push_config enable row level security;
revoke all on public.push_config from anon, authenticated;

create or replace function public.notify_push()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  cfg record;
begin
  select url, secret into cfg from public.push_config where id;
  if cfg.url is null then
    return new;
  end if;
  perform net.http_post(
    url := cfg.url,
    body := jsonb_build_object(
      'type', 'message.created',
      'message', jsonb_build_object(
        'id', new.id,
        'user_id', new.user_id,
        'recipient_id', new.recipient_id,
        'content', new.content,
        'attachment_name', new.attachment_name,
        'attachment_type', new.attachment_type
      )
    ),
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'Authorization', 'Bearer ' || cfg.secret
    ),
    timeout_milliseconds := 5000
  );
  return new;
end;
$$;

revoke execute on function public.notify_push() from public, anon, authenticated;

create trigger messages_notify_push
  after insert on public.messages
  for each row execute function public.notify_push();
